const profileRows = $('Load Learner Profile').all();
const progressRows = $('Load Progress Log').all();

// Parse profile key-value pairs
const profile = {};
for (const row of profileRows) {
  const k = (row.json.setting || '').toLowerCase().replace(/\s+/g, '_');
  const v = row.json.value;
  if (k) profile[k] = v;
}

const targetLanguage = profile.target_language || 'Spanish';
const nativeLanguage = profile.native_language || 'English';
const level = profile.current_level || 'A2';
const learningGoal = profile.learning_goal || 'conversational fluency';
const dailyMinutes = parseInt(profile.daily_minutes) || 15;
const focusAreas = profile.focus_areas || 'vocabulary,grammar,listening';
const interests = profile.interests || 'travel,food,culture';
const weaknesses = profile.known_weaknesses || 'none noted';

// Streak and recent history from progress log
const sessions = progressRows.map(r => r.json).filter(r => r.date);
sessions.sort((a, b) => new Date(b.date) - new Date(a.date));

const today = new Date();
today.setHours(0, 0, 0, 0);

let streak = 0;
let checkDate = new Date(today);
for (const s of sessions) {
  const sessionDate = new Date(s.date);
  sessionDate.setHours(0, 0, 0, 0);
  const diff = Math.floor((checkDate - sessionDate) / 86400000);
  if (diff <= 1) { streak++; checkDate = sessionDate; }
  else break;
}

const totalSessions = sessions.length;
const recentTopics = sessions.slice(0, 10).map(s => s.topic).filter(Boolean);
const recentScores = sessions.slice(0, 10).map(s => parseFloat(s.score)).filter(n => !isNaN(n));
const avgScore = recentScores.length
  ? (recentScores.reduce((a, b) => a + b, 0) / recentScores.length).toFixed(1)
  : null;

// Determine what to focus on today based on rotation
const focusRotation = focusAreas.split(',').map(f => f.trim());
const dayOfYear = Math.floor((today - new Date(today.getFullYear(), 0, 0)) / 86400000);
const todayFocus = focusRotation[dayOfYear % focusRotation.length];

return [{
  json: {
    targetLanguage,
    nativeLanguage,
    level,
    learningGoal,
    dailyMinutes,
    interests,
    weaknesses,
    todayFocus,
    streak,
    totalSessions,
    recentTopics,
    avgScore,
    dateStr: today.toISOString().split('T')[0]
  }
}];

