const rawText = $input.first().json.text || $input.first().json.content?.[0]?.text || '';

let lesson;
try {
  const clean = rawText.replace(/```json|```/g, '').trim();
  lesson = JSON.parse(clean);
} catch(e) {
  return [{ json: { error: 'Parse error', raw: rawText } }];
}

const learner = $('Build Learner Context').first().json;
lesson._meta = { streak: learner.streak, dailyMinutes: learner.dailyMinutes };

return [{ json: lesson }];
